const b = $json.body;
if (!b || !/^[a-f0-9]{32}$/.test(b.id) || b.idempotency_key !== 'plaud:' + b.id || typeof b.transcript !== 'string' || !b.transcript.trim() || b.transcript.length > 100000) {
  throw new Error('Invalid Plaud payload');
}
return [{ json: b }];

const source = $('Validate Plaud payload').first().json;
const raw = $json.message?.content || $json.text || $json.output || $json;
let proposal;
if (typeof raw === 'string') { try { proposal = JSON.parse(raw); } catch { throw new Error('AI did not return JSON'); } } else { proposal = raw; }
if (!proposal || !Array.isArray(proposal.actions) || proposal.actions.length > 20) throw new Error('Invalid actions');
for (const action of proposal.actions) {
  if (!['event', 'task'].includes(action.kind) || typeof action.title !== 'string' || !action.title.trim() || typeof action.evidence !== 'string' || !action.evidence.trim() || typeof action.needs_review !== 'boolean') throw new Error('Invalid action');
  if (action.kind === 'event' && (!action.date || !action.start)) action.needs_review = true;
}
return [{ json: { idempotency_key: source.idempotency_key, recording_id: source.id, recorded_at: source.start_at || source.created_at, timezone: source.timezone || 'UTC', source_transcript: source.transcript, actions: proposal.actions } }];

// SAFETY SWITCH: change to true only after a controlled test and deduplication setup.
const ENABLE_GOOGLE_WRITES = false;
return ENABLE_GOOGLE_WRITES ? $input.all() : [];

const source = $('Validate proposal').first().json;
const output = [];
for (let index = 0; index < source.actions.length; index += 1) {
  const action = source.actions[index];
  if (action.kind !== 'event' || action.needs_review || !action.date || !action.start) continue;
  const start = action.start.includes('T') ? action.start : `${action.date}T${action.start.length === 5 ? action.start + ':00' : action.start}`;
  const end = action.end ? (action.end.includes('T') ? action.end : `${action.date}T${action.end.length === 5 ? action.end + ':00' : action.end}`) : start;
  output.push({ json: { summary: action.title.trim(), description: `${action.description || ''}\n\nPlaud recording reference: ${source.recording_id}#${index}`.trim(), start, end } });
}
return output;

const source = $('Validate proposal').first().json;
const output = [];
for (let index = 0; index < source.actions.length; index += 1) {
  const action = source.actions[index];
  if (action.kind !== 'task') continue;
  const title = action.needs_review ? `[Review] ${action.title.trim()}` : action.title.trim();
  const due = action.date ? `${action.date}T23:59:59.000Z` : undefined;
  output.push({ json: { title, notes: `${action.description || ''}\n\nPlaud recording reference: ${source.recording_id}#${index}`.trim(), due } });
}
return output;
